@st.cache_resource(show_spinner="원본 실행기를 준비하고 있습니다…")
def prepare_frontend():
    directory = Path(tempfile.mkdtemp(prefix="flowery_original_"))
    with zipfile.ZipFile(io.BytesIO(base64.b85decode(FRONTEND_ARCHIVE))) as archive:
        archive.extractall(directory)
    return str(directory)

try:
    frontend_path = prepare_frontend()
except (OSError, ValueError, zipfile.BadZipFile) as exc:
    st.error(f"실행기 파일을 준비하지 못했습니다: {exc}")
    st.stop()

flowery = components.declare_component("flowery_original", path=frontend_path)
flowery(key="flowery_original_game", default=None)
